# Lliçons del mòdul «Màrqueting en l'activitat comercial» (3/4): preu i distribució
L = [
dict(slug='precio-factores-metodos', id='M_precio', orden=15, codigos=['5.1', '5.2', '5.3'], fase=1,
 es=dict(titulo='El precio y cómo se fija', objetivo='Identificar los factores que influyen en el precio y aplicar los métodos de fijación.',
  tira=[[('eco','alegria','Pongo el precio que me parece bonito: 2,50 €.')],[('nexo','esceptico','¿Cuánto te cuesta? ¿Cuánto cobra la competencia? ¿Cuánto está dispuesto a pagar tu cliente?')],[('nexo','guino','Costes, competencia y demanda. Los tres a la vez.')]],
  cos='El <b>precio</b> es la única P que aporta ingresos; las otras son costes. Además comunica: un precio muy bajo puede hacer dudar de la calidad.\n\nInfluyen factores <b>internos</b> (costes, objetivos de la empresa, posicionamiento) y <b>externos</b> (demanda, competencia, situación económica, leyes).\n\nMétodos de fijación: basados en los <b>costes</b> (coste + margen), en la <b>competencia</b> (por encima, igual o por debajo de los rivales) y en la <b>demanda</b> (lo que el cliente valora y está dispuesto a pagar). En la práctica se combinan: el coste marca el mínimo, la demanda el máximo y la competencia indica dónde situarte.',
  ejemplo='Un queso te cuesta 4,10 €. Por debajo no ganas nada (coste). La competencia lo vende a 8 €. Tus clientes exigentes pagarían hasta 10 €. Tu precio debería estar entre 4,10 € y 10 €, cerca de 8 €.',
  errores=['Fijar el precio solo con el coste, sin mirar lo que cobra la competencia ni lo que vale para el cliente.','Pensar que el precio más bajo siempre vende más.'],
  test=[('¿Qué P genera ingresos?',['Producto','Precio','Distribución','Promoción'],1,'Las otras tres suponen costes.'),
   ('El coste del producto marca…',['El precio máximo','El precio mínimo para no perder','El precio de la competencia','El margen de los rivales'],1,'Por debajo del coste pierdes dinero en cada venta.'),
   ('Fijar el precio a partir de lo que el cliente está dispuesto a pagar es un método basado en…',['Los costes','La competencia','La demanda','El margen'],2,'Parte del valor percibido por el cliente.'),
   ('¿Qué factor es externo?',['Los costes de la tienda','Los objetivos de la empresa','Los precios de la competencia','El posicionamiento elegido'],2,'La empresa no los controla.')]),
 ca=dict(titulo='El preu i com es fixa', objetivo='Identificar els factors que influeixen en el preu i aplicar els mètodes de fixació.',
  tira=[[('eco','alegria','Poso el preu que em sembla bonic: 2,50 €.')],[('nexo','esceptico','Quant et costa? Quant cobra la competència? Quant està disposat a pagar el teu client?')],[('nexo','guino','Costos, competència i demanda. Tots tres alhora.')]],
  cos='El <b>preu</b> és l\'única P que aporta ingressos; les altres són costos. A més, comunica: un preu molt baix pot fer dubtar de la qualitat.\n\nHi influeixen factors <b>interns</b> (costos, objectius de l\'empresa, posicionament) i <b>externs</b> (demanda, competència, situació econòmica, lleis).\n\nMètodes de fixació: basats en els <b>costos</b> (cost + marge), en la <b>competència</b> (per sobre, igual o per sota de les rivals) i en la <b>demanda</b> (el que el client valora i està disposat a pagar). A la pràctica es combinen: el cost marca el mínim, la demanda el màxim i la competència indica on situar-te.',
  ejemplo='Un formatge et costa 4,10 €. Per sota no guanyes res (cost). La competència el ven a 8 €. Els teus clients exigents pagarien fins a 10 €. El teu preu hauria de ser entre 4,10 € i 10 €, a prop de 8 €.',
  errores=['Fixar el preu només amb el cost, sense mirar què cobra la competència ni què val per al client.','Pensar que el preu més baix sempre ven més.'],
  test=[('Quina P genera ingressos?',['Producte','Preu','Distribució','Promoció'],1,'Les altres tres suposen costos.'),
   ('El cost del producte marca…',['El preu màxim','El preu mínim per no perdre','El preu de la competència','El marge de les rivals'],1,'Per sota del cost perds diners a cada venda.'),
   ('Fixar el preu a partir del que el client està disposat a pagar és un mètode basat en…',['Els costos','La competència','La demanda','El marge'],2,'Parteix del valor percebut pel client.'),
   ('Quin factor és extern?',['Els costos de la botiga','Els objectius de l\'empresa','Els preus de la competència','El posicionament triat'],2,'L\'empresa no els controla.')])),

dict(slug='margen-umbral-rentabilidad', id='M_margen', orden=16, codigos=['5.4'], fase=1,
 es=dict(titulo='Margen y umbral de rentabilidad', objetivo='Calcular el margen sobre coste y sobre venta y el umbral de rentabilidad de una tienda.',
  tira=[[('eco','alegria','¡Hoy he vendido 300 €! ¡Soy rico!')],[('nexo','paciencia','Resta lo que te costó el producto y el alquiler, la luz, el sueldo…')],[('eco','verguenza','…Me quedan 4 €.'),('nexo','guino','Por eso hay que conocer el margen y el umbral.')]],
  cos='<b>Margen</b> por unidad = precio de venta − coste. En porcentaje se puede calcular <b>sobre el precio de venta</b> (margen ÷ precio) o <b>sobre el coste</b> (margen ÷ coste); no dan el mismo número. Si quieres un margen sobre el precio: <b>precio = coste ÷ (1 − margen)</b>.\n\nLos <b>costes fijos</b> no cambian con las ventas (alquiler, sueldos, luz) y los <b>variables</b> sí (el producto que vendes). El <b>umbral de rentabilidad</b> o punto muerto es la venta mínima para no perder: <b>unidades = costes fijos ÷ (precio − coste variable unitario)</b>. Por encima del umbral, la empresa gana dinero.',
  ejemplo='Compras a 6 € y vendes a 10 €: margen de 4 €, un 40 % sobre el precio y un 66,7 % sobre el coste. Si tus costes fijos son 400 € al mes, necesitas vender 100 unidades al mes solo para quedarte a cero.',
  errores=['Querer un 40 % de margen y multiplicar el coste por 1,4 (eso es un 40 % sobre el coste).','Confundir ventas con beneficio.'],
  test=[('Compras a 6 € y vendes a 10 €. ¿Margen sobre el precio?',['40 %','66,7 %','4 %','60 %'],0,'(10 − 6) ÷ 10 = 0,40.'),
   ('Quieres un 50 % de margen sobre el precio y el producto te cuesta 3 €. ¿A qué precio vendes?',['4,50 €','6 €','3,50 €','5 €'],1,'3 ÷ (1 − 0,5) = 6 €.'),
   ('Costes fijos de 900 €, precio de 15 € y coste variable de 6 €. ¿Umbral en unidades?',['60','100','150','90'],1,'900 ÷ (15 − 6) = 100 unidades.'),
   ('¿Qué es un coste fijo?',['El producto que compras para vender','El alquiler del local','La comisión del datáfono por venta','El envase de cada producto'],1,'No cambia aunque vendas más o menos.')]),
 ca=dict(titulo='Marge i llindar de rendibilitat', objetivo='Calcular el marge sobre cost i sobre venda i el llindar de rendibilitat d\'una botiga.',
  tira=[[('eco','alegria','Avui he venut 300 €! Soc ric!')],[('nexo','paciencia','Resta el que et va costar el producte i el lloguer, la llum, el sou…')],[('eco','verguenza','…Em queden 4 €.'),('nexo','guino','Per això cal conèixer el marge i el llindar.')]],
  cos='<b>Marge</b> per unitat = preu de venda − cost. En percentatge es pot calcular <b>sobre el preu de venda</b> (marge ÷ preu) o <b>sobre el cost</b> (marge ÷ cost); no donen el mateix número. Si vols un marge sobre el preu: <b>preu = cost ÷ (1 − marge)</b>.\n\nEls <b>costos fixos</b> no canvien amb les vendes (lloguer, sous, llum) i els <b>variables</b> sí (el producte que vens). El <b>llindar de rendibilitat</b> o punt mort és la venda mínima per no perdre: <b>unitats = costos fixos ÷ (preu − cost variable unitari)</b>. Per sobre del llindar, l\'empresa guanya diners.',
  ejemplo='Compres a 6 € i vens a 10 €: marge de 4 €, un 40 % sobre el preu i un 66,7 % sobre el cost. Si els teus costos fixos són 400 € al mes, has de vendre 100 unitats al mes només per quedar-te a zero.',
  errores=['Voler un 40 % de marge i multiplicar el cost per 1,4 (això és un 40 % sobre el cost).','Confondre vendes amb benefici.'],
  test=[('Compres a 6 € i vens a 10 €. Marge sobre el preu?',['40 %','66,7 %','4 %','60 %'],0,'(10 − 6) ÷ 10 = 0,40.'),
   ('Vols un 50 % de marge sobre el preu i el producte et costa 3 €. A quin preu el vens?',['4,50 €','6 €','3,50 €','5 €'],1,'3 ÷ (1 − 0,5) = 6 €.'),
   ('Costos fixos de 900 €, preu de 15 € i cost variable de 6 €. Llindar en unitats?',['60','100','150','90'],1,'900 ÷ (15 − 6) = 100 unitats.'),
   ('Què és un cost fix?',['El producte que compres per vendre','El lloguer del local','La comissió del datàfon per venda','L\'envàs de cada producte'],1,'No canvia encara que venguis més o menys.')])),

dict(slug='elasticidad-demanda', id='M_elasticidad', orden=17, codigos=['5.5'], fase=1,
 es=dict(titulo='La elasticidad de la demanda', objetivo='Calcular la elasticidad precio e interpretar si conviene subir o bajar un precio.',
  tira=[[('eco','alegria','He subido la sal un 20 % y vendo casi lo mismo. ¡Subo también las fresas!')],[('nexo','esceptico','La sal no tiene alternativa. Las fresas… el cliente se lleva plátanos.')],[('nexo','guino','Cada producto reacciona distinto al precio. Eso es la elasticidad.')]],
  cos='La <b>elasticidad precio de la demanda</b> mide cuánto cambia la cantidad vendida cuando cambia el precio: <b>E = % variación de la cantidad ÷ % variación del precio</b> (en valor absoluto).\n\nSi E > 1, la demanda es <b>elástica</b>: los clientes reaccionan mucho, y bajar el precio puede aumentar los ingresos. Si E < 1, es <b>inelástica</b>: reaccionan poco, y subir el precio aumenta los ingresos. Son más elásticos los productos con muchos <b>sustitutos</b>, los de capricho y los que suponen un gasto grande; son más inelásticos los de primera necesidad y los que no tienen alternativa.',
  ejemplo='Subes un producto de 2 € a 2,20 € (+10 %) y las ventas bajan de 100 a 85 unidades (−15 %). E = 15 ÷ 10 = 1,5: elástica. Los ingresos pasan de 200 € a 187 €: la subida no compensa.',
  errores=['Subir precios a productos con muchos sustitutos esperando ganar más.','Olvidar el signo: la elasticidad se interpreta en valor absoluto.'],
  test=[('El precio sube un 10 % y las ventas bajan un 5 %. La demanda es…',['Elástica','Inelástica','Unitaria','Perfectamente elástica'],1,'E = 5 ÷ 10 = 0,5 < 1.'),
   ('Con demanda elástica, bajar el precio…',['Reduce siempre los ingresos','Puede aumentar los ingresos','No cambia las ventas','Solo afecta a la competencia'],1,'Las ventas suben más que proporcionalmente.'),
   ('¿Qué producto suele ser más elástico?',['La sal','Un medicamento imprescindible','Una marca de galletas con muchos sustitutos','El agua del grifo'],2,'Si sube, el cliente cambia de marca fácilmente.'),
   ('El precio baja de 10 € a 8 € y las ventas suben de 50 a 70. ¿Qué pasa con los ingresos?',['Bajan de 500 € a 480 €','Suben de 500 € a 560 €','No cambian','Bajan a 400 €'],1,'50 × 10 = 500 €; 70 × 8 = 560 €. Demanda elástica.')]),
 ca=dict(titulo='L\'elasticitat de la demanda', objetivo='Calcular l\'elasticitat preu i interpretar si convé apujar o abaixar un preu.',
  tira=[[('eco','alegria','He apujat la sal un 20 % i en venc gairebé la mateixa. Apujo també les maduixes!')],[('nexo','esceptico','La sal no té alternativa. Les maduixes… el client s\'endú plàtans.')],[('nexo','guino','Cada producte reacciona diferent al preu. Això és l\'elasticitat.')]],
  cos='L\'<b>elasticitat preu de la demanda</b> mesura quant canvia la quantitat venuda quan canvia el preu: <b>E = % variació de la quantitat ÷ % variació del preu</b> (en valor absolut).\n\nSi E > 1, la demanda és <b>elàstica</b>: els clients reaccionen molt, i abaixar el preu pot augmentar els ingressos. Si E < 1, és <b>inelàstica</b>: reaccionen poc, i apujar el preu augmenta els ingressos. Són més elàstics els productes amb molts <b>substituts</b>, els de caprici i els que suposen una despesa gran; són més inelàstics els de primera necessitat i els que no tenen alternativa.',
  ejemplo='Apuges un producte de 2 € a 2,20 € (+10 %) i les vendes baixen de 100 a 85 unitats (−15 %). E = 15 ÷ 10 = 1,5: elàstica. Els ingressos passen de 200 € a 187 €: la pujada no compensa.',
  errores=['Apujar preus de productes amb molts substituts esperant guanyar més.','Oblidar el signe: l\'elasticitat s\'interpreta en valor absolut.'],
  test=[('El preu puja un 10 % i les vendes baixen un 5 %. La demanda és…',['Elàstica','Inelàstica','Unitària','Perfectament elàstica'],1,'E = 5 ÷ 10 = 0,5 < 1.'),
   ('Amb demanda elàstica, abaixar el preu…',['Redueix sempre els ingressos','Pot augmentar els ingressos','No canvia les vendes','Només afecta la competència'],1,'Les vendes pugen més que proporcionalment.'),
   ('Quin producte sol ser més elàstic?',['La sal','Un medicament imprescindible','Una marca de galetes amb molts substituts','L\'aigua de l\'aixeta'],2,'Si puja, el client canvia de marca fàcilment.'),
   ('El preu baixa de 10 € a 8 € i les vendes pugen de 50 a 70. Què passa amb els ingressos?',['Baixen de 500 € a 480 €','Pugen de 500 € a 560 €','No canvien','Baixen a 400 €'],1,'50 × 10 = 500 €; 70 × 8 = 560 €. Demanda elàstica.')])),

dict(slug='estrategias-precio', id='M_estrategias_precio', orden=18, codigos=['5.6'], fase=1,
 es=dict(titulo='Estrategias de precios', objetivo='Elegir la estrategia de precio adecuada para cada situación.',
  tira=[[('eco','alegria','¡Pongo 3,00 € a todo! Redondo y fácil.')],[('nexo','guino','Prueba 2,99 €. Y para el producto nuevo: ¿empiezas caro y bajas, o barato para que lo prueben?')],[('eco','pensativo','¿Hay estrategias para eso?')]],
  cos='Para <b>productos nuevos</b>: <b>descremación</b> (precio alto al principio, para los clientes que pagan más por la novedad, y después se baja) o <b>penetración</b> (precio bajo para ganar clientes rápido).\n\n<b>Precios psicológicos</b>: acabados en 9 o en 5 (2,99 €), precio de prestigio (alto, redondo), precio de referencia («antes 4 €, ahora 3 €»). <b>Precios diferenciales</b>: distintos según el cliente, el momento o la cantidad (descuentos por volumen, 2×1, horas valle, precios para estudiantes). <b>Precio gancho</b>: un producto muy barato para atraer clientes que compran otros con más margen.\n\nCuidado con la <b>guerra de precios</b>: si todos bajan, nadie gana clientes y todos pierden margen.',
  ejemplo='En Mercadeja, si el Súper Estalvi anuncia precios bajísimos y tú lo sigues, pierdes margen. Puede ser mejor diferenciarte con calidad o producto local.',
  errores=['Entrar en una guerra de precios sin tener costes más bajos que la competencia.','Usar el precio gancho en un producto que la gente compra solo (sin comprar nada más).'],
  test=[('Lanzar un móvil nuevo a un precio alto y bajarlo meses después es…',['Penetración','Descremación','Precio gancho','Precio psicológico'],1,'Aprovecha a quien paga por la novedad.'),
   ('Vender la leche muy barata para atraer clientes que compran más cosas es…',['Precio gancho','Descremación','Precio de prestigio','Precio diferencial por volumen'],0,'Se pierde margen en un producto para ganarlo en otros.'),
   ('«2,99 €» en lugar de «3 €» es un precio…',['De penetración','Psicológico','Diferencial','De prestigio'],1,'Se percibe más barato.'),
   ('Caso real · Muchos cines y museos tienen precio reducido para estudiantes y jubilados. ¿Qué estrategia es?',['Precio psicológico','Precio diferencial según el cliente','Descremación','Guerra de precios'],1,'El precio cambia según el tipo de cliente.')]),
 ca=dict(titulo='Estratègies de preus', objetivo='Triar l\'estratègia de preu adequada per a cada situació.',
  tira=[[('eco','alegria','Poso 3,00 € a tot! Rodó i fàcil.')],[('nexo','guino','Prova 2,99 €. I per al producte nou: comences car i baixes, o barat perquè el provin?')],[('eco','pensativo','Hi ha estratègies per a això?')]],
  cos='Per a <b>productes nous</b>: <b>descremació</b> (preu alt al principi, per als clients que paguen més per la novetat, i després es baixa) o <b>penetració</b> (preu baix per guanyar clients ràpidament).\n\n<b>Preus psicològics</b>: acabats en 9 o en 5 (2,99 €), preu de prestigi (alt, rodó), preu de referència («abans 4 €, ara 3 €»). <b>Preus diferencials</b>: diferents segons el client, el moment o la quantitat (descomptes per volum, 2×1, hores vall, preus per a estudiants). <b>Preu ganxo</b>: un producte molt barat per atraure clients que en compren d\'altres amb més marge.\n\nCompte amb la <b>guerra de preus</b>: si tothom abaixa, ningú no guanya clients i tothom perd marge.',
  ejemplo='A Mercadeja, si el Súper Estalvi anuncia preus baixíssims i tu el segueixes, perds marge. Pot ser millor diferenciar-te amb qualitat o producte local.',
  errores=['Entrar en una guerra de preus sense tenir costos més baixos que la competència.','Fer servir el preu ganxo en un producte que la gent compra sol (sense comprar res més).'],
  test=[('Llançar un mòbil nou a un preu alt i abaixar-lo mesos després és…',['Penetració','Descremació','Preu ganxo','Preu psicològic'],1,'Aprofita qui paga per la novetat.'),
   ('Vendre la llet molt barata per atraure clients que compren més coses és…',['Preu ganxo','Descremació','Preu de prestigi','Preu diferencial per volum'],0,'Es perd marge en un producte per guanyar-lo en d\'altres.'),
   ('«2,99 €» en lloc de «3 €» és un preu…',['De penetració','Psicològic','Diferencial','De prestigi'],1,'Es percep més barat.'),
   ('Cas real · Molts cinemes i museus tenen preu reduït per a estudiants i jubilats. Quina estratègia és?',['Preu psicològic','Preu diferencial segons el client','Descremació','Guerra de preus'],1,'El preu canvia segons el tipus de client.')])),

dict(slug='distribucion-canales-intermediarios', id='M_canales', orden=19, codigos=['6.1', '6.2', '6.3'], fase=5,
 es=dict(titulo='La distribución: canales e intermediarios', objetivo='Describir los canales de distribución y el papel de mayoristas y minoristas.',
  tira=[[('eco','pensativo','El queso viaja de la granja a mi tienda… ¿por arte de magia?')],[('nexo','paciencia','Pasa por un mayorista que compra a muchos productores y vende a muchas tiendas.')],[('eco','sorpresa','¡Hay toda una cadena antes de llegar al cliente!')]],
  cos='La <b>distribución</b> lleva el producto desde el fabricante hasta el consumidor en el lugar, el momento y la cantidad que necesita. Funciones: transportar, almacenar, fraccionar (de palés a unidades), surtir (reunir productos de muchos fabricantes), informar y financiar.\n\nEl <b>canal de distribución</b> es el camino que sigue el producto. Según el número de intermediarios: <b>directo</b> (fabricante → consumidor), <b>corto</b> (fabricante → minorista → consumidor) y <b>largo</b> (fabricante → mayorista → minorista → consumidor).\n\nLos <b>mayoristas</b> compran grandes cantidades y venden a otras empresas (B2B): hostelería, tiendas. Los <b>minoristas</b> o detallistas venden al consumidor final (B2C).',
  ejemplo='En Mercadeja, cuando llegas a gran empresa puedes vender a restaurantes y tiendas pequeñas a un precio más bajo pero en volumen: haces de mayorista (B2B).',
  errores=['Pensar que los intermediarios solo encarecen: también transportan, almacenan, fraccionan y reúnen productos.','Confundir el canal corto con el directo.'],
  test=[('Una granja que vende sus quesos por internet a los consumidores usa un canal…',['Largo','Corto','Directo','Mayorista'],2,'No hay ningún intermediario.'),
   ('Fabricante → mayorista → tienda → consumidor es un canal…',['Directo','Corto','Largo','Integrado'],2,'Tiene dos intermediarios.'),
   ('¿Qué función hace el minorista al vender unidades sueltas de lo que compró en cajas?',['Surtido','Fraccionamiento','Financiación','Información'],1,'Divide grandes cantidades en pequeñas.'),
   ('Un mayorista vende sobre todo a…',['Consumidores finales','Otras empresas: tiendas, bares, restaurantes','La Administración','Sus empleados'],1,'Es venta B2B.')]),
 ca=dict(titulo='La distribució: canals i intermediaris', objetivo='Descriure els canals de distribució i el paper de majoristes i detallistes.',
  tira=[[('eco','pensativo','El formatge viatja de la granja a la meva botiga… per art de màgia?')],[('nexo','paciencia','Passa per un majorista que compra a molts productors i ven a moltes botigues.')],[('eco','sorpresa','Hi ha tota una cadena abans d\'arribar al client!')]],
  cos='La <b>distribució</b> porta el producte des del fabricant fins al consumidor al lloc, al moment i en la quantitat que necessita. Funcions: transportar, emmagatzemar, fraccionar (de palets a unitats), assortir (reunir productes de molts fabricants), informar i finançar.\n\nEl <b>canal de distribució</b> és el camí que segueix el producte. Segons el nombre d\'intermediaris: <b>directe</b> (fabricant → consumidor), <b>curt</b> (fabricant → detallista → consumidor) i <b>llarg</b> (fabricant → majorista → detallista → consumidor).\n\nEls <b>majoristes</b> compren grans quantitats i venen a altres empreses (B2B): hostaleria, botigues. Els <b>detallistes</b> o minoristes venen al consumidor final (B2C).',
  ejemplo='A Mercadeja, quan arribes a gran empresa pots vendre a restaurants i botigues petites a un preu més baix però en volum: fas de majorista (B2B).',
  errores=['Pensar que els intermediaris només encareixen: també transporten, emmagatzemen, fraccionen i reuneixen productes.','Confondre el canal curt amb el directe.'],
  test=[('Una granja que ven els formatges per internet als consumidors fa servir un canal…',['Llarg','Curt','Directe','Majorista'],2,'No hi ha cap intermediari.'),
   ('Fabricant → majorista → botiga → consumidor és un canal…',['Directe','Curt','Llarg','Integrat'],2,'Té dos intermediaris.'),
   ('Quina funció fa el detallista en vendre unitats soltes del que va comprar en caixes?',['Assortiment','Fraccionament','Finançament','Informació'],1,'Divideix grans quantitats en petites.'),
   ('Un majorista ven sobretot a…',['Consumidors finals','Altres empreses: botigues, bars, restaurants','L\'Administració','Els seus treballadors'],1,'És venda B2B.')])),

dict(slug='formas-venta-estrategias-distribucion', id='M_formas_venta', orden=20, codigos=['6.4', '6.5'], fase=3,
 es=dict(titulo='Formas de venta y estrategias de distribución', objetivo='Distinguir venta tradicional, autoservicio y venta sin establecimiento y elegir la intensidad de distribución.',
  tira=[[('eco','alegria','¡Ahora soy un supermercado! Los clientes cogen solos lo que quieren.')],[('nexo','senalando','Autoservicio: más clientes con menos personal… pero si la estantería está vacía, nadie te avisa.')],[('eco','sorpresa','¡A reponer!')]],
  cos='Formas de venta: <b>tradicional</b> (el dependiente atiende desde el mostrador), <b>autoservicio</b> (el cliente coge el producto y paga en caja: supermercados), <b>venta asistida</b> (el cliente se mueve libre y hay personal para asesorar: ropa, electrónica) y <b>venta sin establecimiento</b> (por internet, catálogo, teléfono, máquinas expendedoras, a domicilio, venta ambulante).\n\nEstrategias según cuántos puntos de venta: <b>intensiva</b> (en todas partes: chicles, refrescos), <b>selectiva</b> (en algunas tiendas elegidas: electrodomésticos, ropa de marca) y <b>exclusiva</b> (en uno o muy pocos puntos por zona: lujo, coches).',
  ejemplo='En Mercadeja, al pasar a supermercado de proximidad tienes autoservicio con dos cajas y reponedores: atiendes muchos más clientes, pero el orden y la reposición son clave.',
  errores=['Pasar a autoservicio y olvidar el merchandising y la reposición.','Distribuir un producto de lujo en todas partes y perder la imagen de exclusividad.'],
  test=[('En un supermercado el cliente coge el producto y paga en caja. Es…',['Venta tradicional','Autoservicio','Venta sin establecimiento','Venta asistida'],1,'El cliente se sirve solo.'),
   ('Las máquinas expendedoras son…',['Venta tradicional','Venta sin establecimiento','Autoservicio con personal','Distribución exclusiva'],1,'No hay tienda ni personal.'),
   ('Una marca de refrescos que quiere estar en todos los bares y tiendas aplica una distribución…',['Exclusiva','Selectiva','Intensiva','Directa'],2,'Busca el máximo de puntos de venta.'),
   ('Caso real · Rolex solo vende en un número limitado de distribuidores oficiales. ¿Qué estrategia es?',['Intensiva','Selectiva o exclusiva','Venta sin establecimiento','Autoservicio'],1,'Pocos puntos de venta elegidos protegen la imagen de lujo.')]),
 ca=dict(titulo='Formes de venda i estratègies de distribució', objetivo='Distingir venda tradicional, autoservei i venda sense establiment i triar la intensitat de distribució.',
  tira=[[('eco','alegria','Ara soc un supermercat! Els clients agafen sols el que volen.')],[('nexo','senalando','Autoservei: més clients amb menys personal… però si la prestatgeria és buida, ningú no t\'avisa.')],[('eco','sorpresa','A reposar!')]],
  cos='Formes de venda: <b>tradicional</b> (el dependent atén des del taulell), <b>autoservei</b> (el client agafa el producte i paga a la caixa: supermercats), <b>venda assistida</b> (el client es mou lliure i hi ha personal per assessorar: roba, electrònica) i <b>venda sense establiment</b> (per internet, catàleg, telèfon, màquines expenedores, a domicili, venda ambulant).\n\nEstratègies segons quants punts de venda: <b>intensiva</b> (a tot arreu: xiclets, refrescos), <b>selectiva</b> (en algunes botigues triades: electrodomèstics, roba de marca) i <b>exclusiva</b> (en un o molt pocs punts per zona: luxe, cotxes).',
  ejemplo='A Mercadeja, en passar a supermercat de proximitat tens autoservei amb dues caixes i reposadors: atens molts més clients, però l\'ordre i la reposició són clau.',
  errores=['Passar a autoservei i oblidar el marxandatge i la reposició.','Distribuir un producte de luxe a tot arreu i perdre la imatge d\'exclusivitat.'],
  test=[('En un supermercat el client agafa el producte i paga a la caixa. És…',['Venda tradicional','Autoservei','Venda sense establiment','Venda assistida'],1,'El client se serveix sol.'),
   ('Les màquines expenedores són…',['Venda tradicional','Venda sense establiment','Autoservei amb personal','Distribució exclusiva'],1,'No hi ha botiga ni personal.'),
   ('Una marca de refrescos que vol ser a tots els bars i botigues aplica una distribució…',['Exclusiva','Selectiva','Intensiva','Directa'],2,'Busca el màxim de punts de venda.'),
   ('Cas real · Rolex només ven en un nombre limitat de distribuïdors oficials. Quina estratègia és?',['Intensiva','Selectiva o exclusiva','Venda sense establiment','Autoservei'],1,'Pocs punts de venda triats protegeixen la imatge de luxe.')])),

dict(slug='costes-distribucion-logistica-merchandising', id='M_costes_dist', orden=21, codigos=['6.6', '6.8'], fase=2,
 es=dict(titulo='Costes de distribución, logística y merchandising', objetivo='Calcular los costes de distribución de una tienda y aplicar las bases del merchandising.',
  tira=[[('eco','alegria','¡Abro tienda en línea! Los envíos son gratis, ¿no?')],[('nexo','esceptico','Gratis para el cliente. Para ti: embalaje, repartidor, devoluciones…')],[('nexo','guino','Y en la tienda física, coloca bien el producto: eso también vende.')]],
  cos='Los <b>costes de distribución</b> incluyen transporte, almacenaje, stock inmovilizado, mermas (producto que se estropea o se rompe), personal, alquiler del punto de venta y, en la venta en línea, embalaje, envío y devoluciones. Se comparan con las ventas para saber qué canal es rentable.\n\nLa <b>logística</b> organiza el flujo de mercancías: aprovisionamiento, almacén, preparación de pedidos y entrega. El <b>merchandising</b> es el conjunto de técnicas para presentar el producto en el punto de venta: escaparate, situación en la tienda (zonas calientes y frías), altura del lineal (a la altura de los ojos se vende más), cartelería y ambientación.',
  ejemplo='En Mercadeja, la tienda en línea añade 1 € por pedido de embalaje y reparto. Si el pedido medio es pequeño, el margen desaparece.',
  errores=['Olvidar las mermas y las devoluciones al calcular el coste de un canal.','Poner los productos con más margen en la zona fría o en el estante de abajo.'],
  test=[('¿Qué es una merma?',['Un descuento','Producto que se estropea, se rompe o se pierde','Un coste fijo','Un tipo de envío'],1,'Es mercancía que ya no se puede vender.'),
   ('¿Qué altura del lineal vende más?',['El suelo','La altura de los ojos y de las manos','El estante más alto','Da igual'],1,'Es la zona que el cliente ve y alcanza sin esfuerzo.'),
   ('El escaparate y la cartelería forman parte…',['Del merchandising','Del canal largo','De la logística inversa','Del precio'],0,'Son técnicas de presentación en el punto de venta.'),
   ('Caso real · Los supermercados suelen poner los productos básicos (leche, huevos) al fondo. ¿Por qué?',['Para que se conserven mejor','Para que el cliente recorra la tienda y vea más productos','Porque son productos caros','Por normativa'],1,'Obliga a pasar por más pasillos (zonas calientes y frías).')]),
 ca=dict(titulo='Costos de distribució, logística i marxandatge', objetivo='Calcular els costos de distribució d\'una botiga i aplicar les bases del marxandatge.',
  tira=[[('eco','alegria','Obro botiga en línia! Els enviaments són gratuïts, oi?')],[('nexo','esceptico','Gratuïts per al client. Per a tu: embalatge, repartidor, devolucions…')],[('nexo','guino','I a la botiga física, col·loca bé el producte: això també ven.')]],
  cos='Els <b>costos de distribució</b> inclouen transport, emmagatzematge, estoc immobilitzat, mermes (producte que es fa malbé o es trenca), personal, lloguer del punt de venda i, en la venda en línia, embalatge, enviament i devolucions. Es comparen amb les vendes per saber quin canal és rendible.\n\nLa <b>logística</b> organitza el flux de mercaderies: aprovisionament, magatzem, preparació de comandes i lliurament. El <b>marxandatge</b> (merchandising) és el conjunt de tècniques per presentar el producte al punt de venda: aparador, situació a la botiga (zones calentes i fredes), alçada del lineal (a l\'alçada dels ulls es ven més), cartelleria i ambientació.',
  ejemplo='A Mercadeja, la botiga en línia afegeix 1 € per comanda d\'embalatge i repartiment. Si la comanda mitjana és petita, el marge desapareix.',
  errores=['Oblidar les mermes i les devolucions en calcular el cost d\'un canal.','Posar els productes amb més marge a la zona freda o al prestatge de baix.'],
  test=[('Què és una merma?',['Un descompte','Producte que es fa malbé, es trenca o es perd','Un cost fix','Un tipus d\'enviament'],1,'És mercaderia que ja no es pot vendre.'),
   ('Quina alçada del lineal ven més?',['El terra','L\'alçada dels ulls i de les mans','El prestatge més alt','Tant és'],1,'És la zona que el client veu i abasta sense esforç.'),
   ('L\'aparador i la cartelleria formen part…',['Del marxandatge','Del canal llarg','De la logística inversa','Del preu'],0,'Són tècniques de presentació al punt de venda.'),
   ('Cas real · Els supermercats solen posar els productes bàsics (llet, ous) al fons. Per què?',['Perquè es conservin millor','Perquè el client recorri la botiga i vegi més productes','Perquè són productes cars','Per normativa'],1,'Obliga a passar per més passadissos (zones calentes i fredes).')])),
]
